775	function drawScatter(){
776	  const cv = $("#scatter"); if(!cv || !GENES.length) return;
777	  const dpr = window.devicePixelRatio||1;
778	  const W = cv.clientWidth||1060, H = cv.clientHeight||470;
779	  cv.width = W*dpr; cv.height = H*dpr;
780	  const ctx = cv.getContext("2d"); ctx.setTransform(dpr,0,0,dpr,0,0);
781	  const padL=54, padR=16, padT=16, padB=42, lim=1.25;
782	  const X = v => padL + (v+lim)/(2*lim)*(W-padL-padR);
783	  const Y = v => padT + (1-(v+lim)/(2*lim))*(H-padT-padB);
784	  ctx.clearRect(0,0,W,H);
785	  ctx.strokeStyle="#e3d7b8"; ctx.fillStyle="#5d5342"; ctx.font="11px 'IBM Plex Mono',monospace";
786	  for(const t of [-1,-0.5,0,0.5,1]){
787	    ctx.beginPath(); ctx.moveTo(X(t),padT); ctx.lineTo(X(t),H-padB); ctx.stroke();
788	    ctx.beginPath(); ctx.moveTo(padL,Y(t)); ctx.lineTo(W-padR,Y(t)); ctx.stroke();
789	    ctx.fillText(t.toFixed(1), X(t)-8, H-padB+17); ctx.fillText(t.toFixed(1), 24, Y(t)+4);
790	  }
791	  ctx.strokeStyle="#1a1510"; ctx.setLineDash([6,5]); ctx.lineWidth=1.4;
792	  ctx.beginPath(); ctx.moveTo(X(-lim),Y(-lim)); ctx.lineTo(X(lim),Y(lim)); ctx.stroke(); ctx.setLineDash([]);
793	  ctx.fillStyle="#1a1510"; ctx.font="600 12px Archivo,sans-serif";
794	  ctx.fillText("Δ organoid vs conventional 2D  →", W/2-104, H-9);
795	  ctx.save(); ctx.translate(14,H/2+96); ctx.rotate(-Math.PI/2); ctx.fillText("Δ flat-grown, organoid medium →",0,0); ctx.restore();
796	  scatterPts = [];
797	  const hits = GENES.filter(g=>g.f>0 && g.D!=null && g.A!=null);
798	  for(const g of hits){
799	    const x=X(Math.max(-lim,Math.min(lim,g.D))), y=Y(Math.max(-lim,Math.min(lim,g.A)));
800	    scatterPts.push({x,y,g});
801	    ctx.beginPath();
802	    if(g.f===3){ ctx.fillStyle="#1668a0"; ctx.moveTo(x,y-6.5); ctx.lineTo(x+6.5,y); ctx.lineTo(x,y+6.5); ctx.lineTo(x-6.5,y); ctx.closePath(); }
803	    else { ctx.fillStyle = g.f===1 ? "rgba(201,51,24,.8)" : "rgba(169,121,28,.85)"; ctx.arc(x,y,g.g===state.selected?5:3.2,0,7); }
804	    ctx.fill();
805	    if(g.g===state.selected){ ctx.strokeStyle="#1a1510"; ctx.lineWidth=1.8; ctx.beginPath(); ctx.arc(x,y,8.5,0,7); ctx.stroke();
806	      ctx.font="600 12px 'IBM Plex Mono',monospace"; ctx.fillStyle="#1a1510"; ctx.fillText(g.g, x+12, y-8); }
807	  }
808	}
