941	function cpuMorph(out, A, B, t, s, i3, fx){
942	  /* fx mirrors the shader exactly: morph -> intro -> drift -> repulsion */
943	  let lt = Math.min(1, Math.max(0, (t - s*0.38)/0.62));
944	  lt = lt*lt*(3-2*lt);
